const input = $input.first()?.json || {};

const job_id = input.job_id || ('job_recovered_' + Date.now().toString(36));
const intent = input.intent || 'search_private';

let entities = input.entities;
let attempts = 0;
while (typeof entities === 'string' && attempts < 3) {
  try { entities = JSON.parse(entities); } catch(e) { entities = {}; break; }
  attempts++;
}
entities = entities || {};

// ── QUERY VALUE NORMALIZATION: 200 Unicode code points per dynamic value ──
// Applied independently to service and region. Never applied to final query.
function normalizeQueryValue(v) {
  let s = String(v ?? '');
  try { s = s.normalize('NFKC'); } catch(e) {}
  s = s.replace(/["\r\n\t]/g, ' ');
  s = s.replace(/\s+/g, ' ');
  s = s.trim();
  s = Array.from(s).slice(0, 200).join('');
  s = s.trim();
  return s;
}

const hasService = (entities.service != null && String(entities.service).trim() !== '');
const hasRegion = (entities.region != null && String(entities.region).trim() !== '');

if (!hasService && !input.intent) {
  throw new Error("Критическая ошибка: Данные не дошли до узла.");
}

if (intent === 'search_private' && !hasRegion) {
  throw new Error("WF2_MISSING_REGION: search_private требует непустой entities.region; поиск без региона запрещён.");
}

const service = normalizeQueryValue(entities.service);
const region = normalizeQueryValue(entities.region);
const budget_min = entities.budget_min || 0;
const budget_max = entities.budget_max || 999999999;

// retrieval cutoff for the `after:` operator: 30-day lookback (UTC, YYYY-MM-DD).
// `after:{cutoff}` is retrieval precision only and is never freshness evidence.
const cutoff = new Date(Date.now() - 30 * 86400000).toISOString().slice(0, 10);

// negative suffix for PRIVATE retrieval (fixed)
const NEGATIVE = '-вакансия -резюме -прайс -каталог -магазин';

const queries = [];

if (intent === 'search_private') {
  // PRIVATE: ровно 14 query templates (6 targeted, 8 general)
  queries.push({ json: { query: `site:vk.com "ищу мастера" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'vk', retrieval_profile: 'vk_post', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `site:vk.com "нужен мастер" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'vk', retrieval_profile: 'vk_post', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `site:t.me "ищу мастера" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'telegram', retrieval_profile: 'telegram_post', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `site:t.me "нужен мастер" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'telegram', retrieval_profile: 'telegram_post', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `site:poisk-pro.ru "заказ" ${service} ${region} after:${cutoff}`, source_platform: 'poisk-pro', retrieval_profile: 'poisk_pro_order', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `site:pro.petrovich.ru inurl:orders -inurl:orders-btob ${service} ${region} after:${cutoff}`, source_platform: 'petrovich', retrieval_profile: 'petrovich_order', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"ищу мастера" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'general', retrieval_profile: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"нужен мастер" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'general', retrieval_profile: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"нужен специалист" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'general', retrieval_profile: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"кто может сделать" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'general', retrieval_profile: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"посоветуйте мастера" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'general', retrieval_profile: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"порекомендуйте мастера" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'general', retrieval_profile: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"нужно сделать" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'general', retrieval_profile: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"требуется мастер" ${service} ${region} after:${cutoff} ${NEGATIVE}`, source_platform: 'general', retrieval_profile: 'general', region, job_id, service, budget_min, budget_max, intent } });
} else {
  // B2B: ровно 10 query templates
  queries.push({ json: { query: `${service} ${region} vsem-podryad.ru "субподряд"`, source_platform: 'vsem-podryad', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} vsem-podryad.ru "заявка"`, source_platform: 'vsem-podryad', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} t.me "субподряд"`, source_platform: 'telegram', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"ищем подрядчика" ${service} ${region}`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"требуется подрядчик" ${service} ${region}`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"ищем субподрядчика" ${service} ${region}`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"требуется бригада" ${service} ${region}`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} "заявка на субподряд"`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} "бригада на объект"`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} "объём работ" подрядчик`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
}

// DIAG V2: Initialize accumulator for in-scope jobs
(function() {
  try {
    const normalize = (value) => String(value ?? '').trim().toLowerCase().replace(/ё/g, 'е').replace(/[‐‑‒–—−]/g, '-');
    const diagInScope = intent === 'search_private' && normalize(service).includes('вентиляц') && (/(^|[^а-яa-z0-9])спб([^а-яa-z0-9]|$)/u.test(normalize(region)) || normalize(region).includes('петербург'));
    if (!diagInScope) return;
    const diagKey = 'wf2_diag_v2_' + job_id;
    const sd = $getWorkflowStaticData('global');
    const now = Date.now();
    for (const k of Object.keys(sd)) {
      if (k.startsWith('wf2_diag_v2_') && sd[k]?.ts && (now - sd[k].ts > 86400000)) {
        delete sd[k];
      }
    }
    sd[diagKey] = { ts: now, queryCount: queries.length, queriesByPlatform: {} };
    for (const q of queries) {
      const p = q.json.source_platform || 'unknown';
      sd[diagKey].queriesByPlatform[p] = (sd[diagKey].queriesByPlatform[p] || 0) + 1;
    }
  } catch(e) { /* fail-open */ }
})();

return queries;

// TEMP Finalize WF2 Funnel V2 — reads transient accumulator, builds compact diagnostic
// Runs when Loop Queries completes (output 0 = DONE).
// Fail-open: any error returns original items unchanged with emit=false.

try {
  const normalize = (value) => String(value ?? '').trim().toLowerCase().replace(/ё/g, 'е').replace(/[‐‑‒–—−]/g, '-');
  const items = $input.all();
  const firstItem = (items && items.length > 0) ? (items[0].json || {}) : {};

  let intent = '', service = '', region = '', jobId = '';
  try {
    const triggerData = $('Trigger').first().json;
    intent = triggerData.intent || '';
    jobId = triggerData.job_id || '';
    let entities = triggerData.entities;
    let attempts = 0;
    while (typeof entities === 'string' && attempts < 3) {
      try { entities = JSON.parse(entities); } catch(e) { entities = {}; break; }
      attempts++;
    }
    entities = entities || {};
    service = entities.service || '';
    region = entities.region || '';
  } catch(e) {}

  if (!service || !region) {
    service = firstItem.service || service;
    region = firstItem.region || region;
  }
  if (!jobId) jobId = firstItem.job_id || '';

  intent = normalize(intent);
  service = normalize(service);
  region = normalize(region);

  const inScope = intent === 'search_private' && service.includes('вентиляц') && (/(^|[^а-яa-z0-9])спб([^а-яa-z0-9]|$)/u.test(region) || region.includes('петербург'));

  let emit = false;
  let diagMessage = '';

  if (inScope) {
    const diagKey = 'wf2_diag_v2_' + jobId;
    const sd = $getWorkflowStaticData('global');
    const acc = sd[diagKey];

    if (acc) {
      const lines = ['TEMP WF2 FUNNEL DIAGNOSTIC V2'];
      lines.push('Job: ' + jobId);
      lines.push('Intent: ' + intent + ' | Svc: ' + service + ' | Region: ' + region);
      lines.push('Queries: ' + (acc.queryCount || 0));
      if (acc.queriesByPlatform) {
        const plat = Object.entries(acc.queriesByPlatform).map(function(e) { return e[0] + ':' + e[1]; }).join(' ');
        lines.push('ByPlatform: ' + plat);
      }
      lines.push('SerpOrganic: ' + (acc.serperOrganicTotal || 0) + ' | URL: ' + (acc.extractedUrlTotal || 0));
      lines.push('ClassIn: ' + (acc.classificationInput || 0) + ' D:' + (acc.demandCount || 0) + ' S:' + (acc.supplyCount || 0) + ' A:' + (acc.ambiguousCount || 0));
      lines.push('Keep: ' + (acc.keepCount || 0) + ' | Reject: ' + (acc.rejectCount || 0));
      if (acc.reasonCodes) lines.push('Codes: ' + JSON.stringify(acc.reasonCodes));
      lines.push('FltPass: ' + (acc.filterEmptyPassed || 0) + ' | LoopUrl: ' + (acc.loopUrlsEntered || 0));
      lines.push('FCAtt: ' + (acc.firecrawlAttempted || 0) + ' | FCUsable: ' + (acc.firecrawlUsable || 0));
      lines.push('CntOut: ' + (acc.extractContactsOutput || 0) + ' | WithCnt: ' + (acc.contactPresenceCount || 0));
      lines.push('AppendOK: ' + (acc.appendLeadSuccessOutput || 0));

      diagMessage = lines.join('\n');
      if (diagMessage.length > 3500) diagMessage = diagMessage.slice(0, 3500);

      delete sd[diagKey];
      emit = true;
    } else {
      diagMessage = 'TEMP WF2 FUNNEL DIAGNOSTIC V2\nJob: ' + jobId + '\nStatus: INSTRUMENTATION STATE MISSING';
      emit = true;
    }
  }

  return items.map(function(item, idx) {
    if (idx === 0) {
      return { json: Object.assign({}, item.json, { _temp_wf2_diag_v1_emit: emit, _temp_wf2_diag_v1_message: diagMessage }) };
    }
    return { json: Object.assign({}, item.json, { _temp_wf2_diag_v1_emit: false, _temp_wf2_diag_v1_message: '' }) };
  });
} catch(e) {
  return $input.all();
}

let jobId = '';
try {
  jobId = $('Trigger').first().json.job_id || '';
} catch(e) {}
if (!jobId) {
  jobId = $input.first()?.json?.job_id || '';
}
if (!jobId) {
  throw new Error('Prepare Analyst Trigger: job_id missing');
}

let requested_count = null;
try {
  const r = $('Trigger').first().json.requested_count;
  if (r !== undefined && r !== null && r !== '') requested_count = Number(r);
} catch(e) {}

let accepted_count = 0;
try {
  const sd = $getWorkflowStaticData('global');
  const key = 'wf2_accepted_' + jobId;
  if (sd && sd[key]) accepted_count = sd[key];
} catch(e) {}

return [{
  json: {
    job_id: jobId,
    entity_type: 'lead',
    accepted_count: accepted_count,
    requested_count: requested_count
  }
}];

const item = $input.first();
if (!item || !item.json) return [{ json: { skip: true, serper_unusable: true } }];
const ctx = item.json;
const query = ctx.query;
const sp = ctx.source_platform;
const rg = ctx.region;
const sv = ctx.service;
const itn = ctx.intent;
const jid = ctx.job_id;
if (!query || !sp || !rg || !sv || !itn || !jid) return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_CONTEXT_MISSING' } }];
if (!item.binary || !item.binary.serperResult) return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_MISSING' } }];
let raw;
try { const buf = await this.helpers.getBinaryDataBuffer(0, 'serperResult'); raw = buf.toString('utf8').replace(/^\uFEFF/, '').trim(); }
catch(e) { return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_READ_FAILED' } }]; }
if (!raw) return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_EMPTY' } }];
let parsed;
try { parsed = JSON.parse(raw); } catch(e) { return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_MALFORMED' } }]; }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_INVALID' } }];
const organic = Array.isArray(parsed.organic) ? parsed.organic : (Array.isArray(parsed.serperResult && parsed.serperResult.organic) ? parsed.serperResult.organic : []);

// ── RETRIEVAL PROFILES (host gate evaluated before path gate) ──
function parseUrlGate(url) {
  try {
    const u = new URL(url);
    if (u.protocol !== 'http:' && u.protocol !== 'https:') return null;
    let h = u.hostname.toLowerCase();
    if (h.endsWith('.')) h = h.slice(0, -1);
    if (h.startsWith('www.')) h = h.slice(4);
    return { host: h, pathname: u.pathname };
  } catch(e) { return null; }
}
function isVkPost(url) {
  const p = parseUrlGate(url);
  if (!p) return false;
  if (!(p.host === 'vk.com' || p.host.endsWith('.vk.com'))) return false;
  return /^\/wall-?\d+_\d+$/.test(p.pathname);
}
function isTelegramPost(url) {
  const p = parseUrlGate(url);
  if (!p) return false;
  if (!(p.host === 't.me' || p.host === 'telegram.me')) return false;
  return /^\/s\/[^/]+\/\d+\/?$/.test(p.pathname) || /^\/[^/]+\/\d+\/?$/.test(p.pathname);
}
function isPoiskProOrder(url) {
  const p = parseUrlGate(url);
  if (!p || p.host !== 'poisk-pro.ru') return false;
  return /^\/order\/[0-9]+(?:\/[^/]+)?\/?$/.test(p.pathname);
}
const PETROVICH_FORBIDDEN = new Set(['orders-btob','profile','profiles','member','members','catalog','catalogue','master','masters']);
function isPetrovichOrder(url) {
  const p = parseUrlGate(url);
  if (!p || p.host !== 'pro.petrovich.ru') return false;
  let path = p.pathname;
  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
  const parts = path.split('/');
  if (parts[0] !== '') return false;
  const segs = parts.slice(1);
  if (segs.some(function(s){ return s === ''; })) return false;
  if (segs.length === 0) return false;
  const orderIdx = segs.indexOf('orders');
  if (orderIdx === -1) return false;
  if (segs.indexOf('orders', orderIdx + 1) !== -1) return false;
  if (orderIdx > 1) return false;
  if (orderIdx + 1 >= segs.length) return false;
  if (!/^[0-9]+$/.test(segs[segs.length - 1])) return false;
  for (let i = 0; i < orderIdx; i++) { if (PETROVICH_FORBIDDEN.has(segs[i])) return false; }
  for (let i = orderIdx + 1; i < segs.length - 1; i++) { if (PETROVICH_FORBIDDEN.has(segs[i])) return false; }
  return true;
}
function profilePass(intent, rp, url) {
  if (intent !== 'search_private') return true;
  if (rp === 'vk_post') return isVkPost(url);
  if (rp === 'telegram_post') return isTelegramPost(url);
  if (rp === 'poisk_pro_order') return isPoiskProOrder(url);
  if (rp === 'petrovich_order') return isPetrovichOrder(url);
  if (rp === 'general') return parseUrlGate(url) !== null;
  return true;
}

const SOURCE_TARGETED = new Set(['youla','vk','telegram','poisk-pro','petrovich','vsem-podryad']);
const limit = SOURCE_TARGETED.has(sp) ? 10 : 3;
const rp = (ctx.retrieval_profile != null) ? ctx.retrieval_profile : null;
const topN = organic.slice(0, limit);

function clipS(s, n) { s = (s == null) ? '' : String(s); return s.length > n ? s.slice(0, n) : s; }
function traceKey(rank, url) { return [jid, query, String(rank), url].join('|'); }
function dateLikeMeta(entry) {
  const out = [];
  try {
    if (!entry || typeof entry !== 'object') return out;
    for (const k of Object.keys(entry)) {
      if (/date|time|publish|posted|created|updated/i.test(k)) {
        const v = entry[k];
        if (v == null) continue;
        if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') out.push({ field_name: k, value: clipS(v, 120) });
      }
    }
  } catch(e) {}
  return out;
}
function serperDateRaw(entry) {
  if (!entry || typeof entry !== 'object') return '';
  const v = entry.date;
  if (v === undefined || v === null) return '';
  const t = typeof v;
  if (t === 'string' || t === 'number' || t === 'boolean') {
    const s = String(v);
    return s.length > 120 ? s.slice(0, 120) : s;
  }
  return '';
}
function buildTop10Diag() {
  const rows = [];
  try {
    const max = Math.min(organic.length, 10);
    for (let i = 0; i < max; i++) {
      const e = organic[i];
      const rank = i + 1;
      let source_profile_match = false;
      let selected_by_remediated_logic = false;
      let selection_reject_reason = '';
      if (rank > limit) {
        selection_reject_reason = 'OUTSIDE_LIMIT';
      } else if (!e || !e.link) {
        selection_reject_reason = 'MISSING_LINK';
      } else if (!profilePass(itn, rp, e.link)) {
        selection_reject_reason = 'OFF_PROFILE';
      } else {
        source_profile_match = true;
        selected_by_remediated_logic = true;
      }
      rows.push({
        rank: rank,
        source_profile_match: source_profile_match,
        selected_by_remediated_logic: selected_by_remediated_logic,
        selection_reject_reason: selection_reject_reason,
        link: clipS(e && e.link, 500),
        title: clipS(e && e.title, 250),
        snippet: clipS(e && e.snippet, 500),
        raw_keys: (e && typeof e === 'object') ? Object.keys(e) : [],
        date_like_metadata: dateLikeMeta(e)
      });
    }
  } catch(e) {}
  return rows;
}

const results = [];
for (let idx = 0; idx < topN.length; idx++) {
  const entry = topN[idx];
  if (!entry || !entry.link) continue;
  if (!profilePass(itn, rp, entry.link)) continue;
  const rank = idx + 1;
  results.push({
    json: {
      url: entry.link,
      title: entry.title || '',
      snippet: entry.snippet || '',
      source_platform: sp,
      query: query,
      job_id: jid,
      intent: itn,
      service: sv,
      region: rg,
      budget_min: ctx.budget_min !== undefined ? ctx.budget_min : 0,
      budget_max: ctx.budget_max !== undefined ? ctx.budget_max : 999999999,
      organic_rank: rank,
      candidate_trace_key: traceKey(rank, entry.link),
      serper_date_raw: serperDateRaw(entry),
      retrieval_profile: rp
    }
  });
}
if (results.length > 0) { results[0].json._diag_serper_top10 = buildTop10Diag(); }
(function() {
  try {
    var dk = 'wf2_diag_v2_' + jid;
    var sd = $getWorkflowStaticData('global');
    if (sd[dk]) {
      sd[dk].serperOrganicTotal = (sd[dk].serperOrganicTotal || 0) + organic.length;
      sd[dk].extractedUrlTotal = (sd[dk].extractedUrlTotal || 0) + results.length;
      sd[dk].ts = Date.now();
    }
  } catch(e) {}
})();
return results.length > 0 ? results : [{ json: { skip: true } }];

// ── Classify Private Candidates v5 zone rules ──
// Deterministic DEMAND/SUPPLY/AMBIGUOUS classification for search_private.
// Non-search_private items passthrough unchanged.
// SUPPLY candidates are rejected before Firecrawl.

const classificationVersion = "private_rules_v5";
const classifierBuildId = "v5_zone_rules_001";

function getIntent(item) {
  if (item.json && item.json.intent) return item.json.intent;
  try {
    const ti = $('Trigger').first();
    if (ti && ti.json && ti.json.intent) return ti.json.intent;
  } catch(e) {}
  return '';
}
function hostname(url) {
  if (!url || typeof url !== 'string') return '';
  let s = url.trim().toLowerCase();
  const schemeIdx = s.indexOf('://');
  if (schemeIdx !== -1) s = s.slice(schemeIdx + 3);
  const slashIdx = s.indexOf('/');
  if (slashIdx !== -1) s = s.slice(0, slashIdx);
  const colonIdx = s.lastIndexOf(':');
  if (colonIdx !== -1) s = s.slice(0, colonIdx);
  if (s.startsWith('www.')) s = s.slice(4);
  return s;
}
function pathname(url) {
  if (!url || typeof url !== 'string') return '';
  let s = url.trim().toLowerCase();
  const schemeIdx = s.indexOf('://');
  if (schemeIdx !== -1) s = s.slice(schemeIdx + 3);
  const slashIdx = s.indexOf('/');
  if (slashIdx === -1) return '/';
  s = s.slice(slashIdx);
  const qIdx = s.indexOf('?');
  if (qIdx !== -1) s = s.slice(0, qIdx);
  const fIdx = s.indexOf('#');
  if (fIdx !== -1) s = s.slice(0, fIdx);
  return s;
}
function hasServicePath(url) {
  const p = pathname(url);
  return p.includes('/uslugi/') || p.includes('/promo/') || p.includes('/service/') || p.includes('/remont/') || p.includes('montazh') || p.includes('montaj') || p.includes('ventil') || p.includes('ventilyats');
}
function hasServiceContext(text) {
  return text.includes('монтаж') || text.includes('вентиляц') || text.includes('ventil') || text.includes('ventilyats');
}
function isProfiHost(url) { const h = hostname(url); return h === 'profi.ru' || h.endsWith('.profi.ru'); }
function isYoulaHost(url) { const h = hostname(url); return h === 'youla.ru' || h.endsWith('.youla.ru'); }
function isProfiServiceZone(url) { if (!isProfiHost(url)) return false; const p = pathname(url); return /^\/geo-[^/]+\/remont(?:\/|$)/.test(p); }
function isYoulaServiceZone(url, lower) { if (!isYoulaHost(url)) return false; const p = pathname(url); return p.includes('/uslugi/') && hasServiceContext(lower); }
function isPoiskProHost(url) { const h = hostname(url); return h === 'poisk-pro.ru' || h.endsWith('.poisk-pro.ru'); }
function isPetrovichHost(url) { const h = hostname(url); return h === 'pro.petrovich.ru' || h.endsWith('.pro.petrovich.ru'); }
function isPoiskProOrder(url) { if (!isPoiskProHost(url)) return false; const p = pathname(url); return /^\/order\/\d+(?:\/|$)/.test(p); }
function isPetrovichOrder(url) { if (!isPetrovichHost(url)) return false; const p = pathname(url); const hasOrdersPath = p.includes('/orders/') || p.includes('/orders-btob/'); if (!hasOrdersPath) return false; return /\/\d+$/.test(p); }

function isR00ServiceProviderPage(url, lower) {
  if (isProfiServiceZone(url)) return true;
  if (isYoulaServiceZone(url, lower)) return true;
  if (!hasServicePath(url)) return false;
  return lower.includes('под ключ') || lower.includes('компания') || lower.includes('стоимость') || lower.includes('цены') || lower.includes('скидкой') || lower.includes('специалиста готовы') || lower.includes('специалисты готовы') || lower.includes('найдите частного') || lower.includes('исполнителей') || lower.includes('платная доска объявлений') || lower.includes('хотите установить') || lower.includes('хотите купить');
}
function isR01MarketplacePromo(url, lower) {
  if (!isProfiHost(url)) return false;
  const p = pathname(url);
  if (!p.includes('/promo/')) return false;
  return lower.includes('специалиста готовы') || lower.includes('специалисты готовы') || lower.includes('найдите') || lower.includes('скидкой') || lower.includes('на нашем сайте') || lower.includes('рубл') || lower.includes('исполнителей');
}
function isR02ExecutorCatalog(lower) {
  const hasExecListing = lower.includes('исполнител');
  if (!hasExecListing) return false;
  return hasServiceContext(lower);
}
function isR03CompanyMarketing(lower) {
  if (!lower.includes('компания')) return false;
  return hasServiceContext(lower);
}
function isR04SelfPromotion(lower) {
  if (lower.includes('наша компания')) return true;
  if (lower.includes('принимает заказы') && !lower.includes('ищу')) return true;
  if (lower.includes('оказываем услуги')) return true;
  if (lower.includes('выполняем') && lower.includes('монтаж')) return true;
  if (lower.includes('бригада') && lower.includes('предлагает')) return true;
  if (lower.includes('звоните')) return true;
  if (lower.includes('оставить заявку') && (lower.includes('монтаж') || lower.includes('вентиляц'))) return true;
  return false;
}
function isR05Demand(url, lower) {
  const p = pathname(url);
  if (p.includes('/request/') || p.includes('/requests/')) return true;
  if (p.includes('/zayavk') || p.includes('/zakaz')) return true;
  if (lower.includes('ищу бригаду')) return true;
  if (lower.includes('нужна бригада')) return true;
  if (lower.includes('ищем исполнител')) return true;
  if (lower.includes('посоветуйте бригаду')) return true;
  if (lower.includes('поделитесь контактами')) return true;
  if (lower.includes('кто может сделать')) return true;
  if (lower.includes('ищем мастер')) return true;
  if (lower.includes('ищу мастер')) return true;
  if (lower.includes('заявки на субподряд')) return true;
  const hasReq = lower.includes('требуется') && (lower.includes('выполнить') || lower.includes('сделать'));
  const hasResources = lower.includes('расходники предоставим') || lower.includes('леса предоставим') || lower.includes('объемы внушительные');
  const hasRegion = lower.includes('регион:');
  const hasAddress = lower.includes('адрес:');
  const taskSignals = [hasReq, hasResources, hasRegion, hasAddress].filter(Boolean).length;
  if (taskSignals >= 2) return true;
  return false;
}

function buildDebug(url, title, snippet, idx) {
  const lower = (title + ' ' + snippet).toLowerCase();
  const path = pathname(url);
  return {
    classifier_build_id: classifierBuildId,
    input_index: idx,
    path_normalized: path,
    lower_preview: lower.slice(0, 150),
    predicates: {
      hasServicePath: hasServicePath(url),
      hasServiceContext: hasServiceContext(lower),
      isProfiHost: isProfiHost(url),
      isYoulaHost: isYoulaHost(url),
      isProfiServiceZone: isProfiServiceZone(url),
      isYoulaServiceZone: isYoulaServiceZone(url, lower),
      isPoiskProHost: isPoiskProHost(url),
      isPetrovichHost: isPetrovichHost(url),
      isPoiskProOrder: isPoiskProOrder(url),
      isPetrovichOrder: isPetrovichOrder(url),
      R00_SERVICE_PROVIDER_PAGE: isR00ServiceProviderPage(url, lower),
      R01_MARKETPLACE_PROMO: isR01MarketplacePromo(url, lower),
      R02_EXECUTOR_CATALOG: isR02ExecutorCatalog(lower),
      R03_COMPANY_MARKETING: isR03CompanyMarketing(lower),
      R04_SELF_PROMOTION: isR04SelfPromotion(lower),
      R05_DEMAND: isR05Demand(url, lower)
    }
  };
}

function classify(url, title, snippet) {
  const lower = (title + ' ' + snippet).toLowerCase();
  if (isPoiskProOrder(url))                     return { cls: 'DEMAND', codes: ['R05A_POISKPRO_ORDER'] };
  if (isPetrovichOrder(url))                     return { cls: 'DEMAND', codes: ['R05B_PETROVICH_ORDER'] };
  if (isR00ServiceProviderPage(url, lower))      return { cls: 'SUPPLY', codes: ['R00_SERVICE_PROVIDER_PAGE'] };
  if (isR01MarketplacePromo(url, lower))          return { cls: 'SUPPLY', codes: ['R01_MARKETPLACE_PROMO'] };
  if (isR02ExecutorCatalog(lower))                return { cls: 'SUPPLY', codes: ['R02_EXECUTOR_CATALOG'] };
  if (isR03CompanyMarketing(lower))               return { cls: 'SUPPLY', codes: ['R03_COMPANY_MARKETING'] };
  if (isR04SelfPromotion(lower))                  return { cls: 'SUPPLY', codes: ['R04_SELF_PROMOTION'] };
  if (isR05Demand(url, lower))                    return { cls: 'DEMAND', codes: ['R05_DEMAND'] };
  return { cls: 'AMBIGUOUS', codes: ['R06_DEFAULT'] };
}

