function nfkcNorm(s) { return String(s||'').toLowerCase().replace(/ё/g,'е').replace(/[‐‑‒–—−]/g,'-'); }

function normalizeServiceText(s) {
  var t = nfkcNorm(s);
  t = t.replace(/[^\w\sа-яё/\-]/gi,' ').replace(/-/g,' ').replace(/\s+/g,' ').trim();
  return t;
}

var GENERIC_STOPWORDS_SET = {};
['услуга','услуги','работа','работы','выполнение','выполнить','оказание','оказать','нужен','нужна','нужно','требуется','ищу','заказ','заказать','мастер','специалист','бригада','по','для','на','в','с','и'].forEach(function(w){GENERIC_STOPWORDS_SET[w]=true;});

function tokenize(s) { return s.split(/\s+/).filter(function(t){return t.length>0;}); }
function removeStopwords(tokens) { return tokens.filter(function(t){return !GENERIC_STOPWORDS_SET[t];}); }

var RUS_SUFFIXES = ['иями','ями','ами','иях','ого','его','ому','ему','ыми','ими','ах','ях','ов','ев','ам','ям','ой','ей','ом','ем','ую','юю','ая','яя','ое','ее','ые','ие','ый','ий','а','я','ы','и','у','ю','е'];
function stemWord(w) {
  for (var i=0;i<RUS_SUFFIXES.length;i++) { var s=RUS_SUFFIXES[i]; if (w.endsWith(s) && w.length-s.length>=4) return w.slice(0,w.length-s.length); }
  return w;
}
function stemTokens(tokens) { return tokens.map(stemWord); }

var ACT_GROUPS = {
  INSTALL:     ['монтаж','монтировать','смонтировать','установк','установить'],
  DISMANTLE:   ['демонтаж','демонтировать'],
  REPAIR:      ['ремонт','ремонтировать','отремонтировать','починить'],
  MAINTENANCE: ['обслуживан','обслужить','техобслуживан','сервисн обслуживан'],
  DESIGN:      ['проектирован','проектировать','спроектировать','разработк проект'],
  COMMISSION:  ['пусконаладк','пуско наладк','пусконаладочн работ'],
  REPLACE:     ['замен','заменить'],
  CLEAN:       ['очистк','чистк','очистить','почистить']
};

var NORM_ACT = {};
for (var gn in ACT_GROUPS) {
  NORM_ACT[gn] = ACT_GROUPS[gn].map(function(e){return stemTokens(removeStopwords(tokenize(normalizeServiceText(e))));});
}

function parseServiceClause(serviceStr) {
  var s = normalizeServiceText(serviceStr);
  var orParts = s.split(/\s+или\s+/);
  var alternatives = [];
  for (var i=0;i<orParts.length;i++) {
    var subParts = orParts[i].split(/\s*\/\s*/);
    for (var j=0;j<subParts.length;j++) {
      var sub = subParts[j].trim(); if (!sub) continue;
      var andParts = sub.split(/\s+и\s+/);
      var conjuncts = [];
      for (var k=0;k<andParts.length;k++) {
        var ap = andParts[k].trim(); if (!ap) continue;
        var tokens = removeStopwords(tokenize(ap));
        tokens = stemTokens(tokens);
        conjuncts.push(tokens);
      }
      if (conjuncts.length>0) alternatives.push(conjuncts);
    }
  }
  return alternatives;
}

function containsContiguousSeq(haystack, needle) {
  if (needle.length===0) return false;
  for (var start=0;start<=haystack.length-needle.length;start++) {
    var match=true;
    for (var ti=0;ti<needle.length;ti++) { if (haystack[start+ti]!==needle[ti]){match=false;break;} }
    if (match) return true;
  }
  return false;
}

function unitSatisfiesAlt(unitTokens, alternative) {
  for (var c=0;c<alternative.length;c++) {
    var conj=alternative[c]; if (conj.length===0) continue;
    if (!containsContiguousSeq(unitTokens, conj)) return false;
  }
  return true;
}

function splitEvidenceUnits(text) {
  var units=[];
  var paragraphs=text.split(/\n\s*\n/);
  for (var p=0;p<paragraphs.length;p++) {
    var para=paragraphs[p].trim(); if(!para) continue;
    var headingParts=para.split(/(?:^|\n)#{1,6}\s+/);
    for (var h=0;h<headingParts.length;h++) {
      var hp=headingParts[h].trim(); if(!hp) continue;
      var listParts=hp.split(/(?:^|\n)[-*•]\s+/);
      for (var l=0;l<listParts.length;l++) { var lp=listParts[l].trim(); if(lp) units.push(lp); }
    }
  }
  return units.length>0?units:[text];
}

function unitHasNegatedMatch(rawUnit, alternative) {
  var lower=rawUnit.toLowerCase();
  if (!/\b(?:не|без|кроме|исключая)\b/.test(lower)) return false;
  var rawTokens=lower.split(/\s+/);
  var negPositions=[];
  for (var rt=0;rt<rawTokens.length;rt++) { if (/^(не|без|кроме|исключая)$/.test(rawTokens[rt])) negPositions.push(rt); }
  if (negPositions.length===0) return false;
  for (var c=0;c<alternative.length;c++) {
    var conj=alternative[c]; if (conj.length===0) continue;
    for (var rt2=0;rt2<=rawTokens.length-conj.length;rt2++) {
      var cm=true;
      for (var ct=0;ct<conj.length;ct++) { if (stemWord(normalizeServiceText(rawTokens[rt2+ct]))!==conj[ct]){cm=false;break;} }
      if (cm) {
        for (var np=0;np<negPositions.length;np++) { if (Math.abs(negPositions[np]-rt2)<=3) return true; }
      }
    }
  }
  return false;
}

function computeServiceMatch(ctxServiceArg, evidenceText) {
  if (!ctxServiceArg||ctxServiceArg.trim()==='') return true;
  var alternatives=parseServiceClause(ctxServiceArg);
  if (alternatives.length===0) return true;
  var rawUnits=splitEvidenceUnits(evidenceText);
